  4	public final class RadixSort {
  5	    private static final int RADIX = 10;
  6	
  7	    private RadixSort() {
  8	    }
  9	
 10	    public static void sort(int[] values) {
 11	        InputAnalysis input = analyze(values);
 12	        sortValidated(input.values(), input.maxValue());
 13	    }
 14	
 15	    public static int[] sortedCopy(int[] values) {
 16	        InputAnalysis input = analyze(values);
 17	        int[] copy = Arrays.copyOf(input.values(), input.values().length);
 18	        sortValidated(copy, input.maxValue());
 19	        return copy;
 20	    }
 21	
 22	    private static void sortValidated(int[] values, int maxValue) {
 23	        if (values.length < 2) {
 24	            return;
 25	        }
 26	
 27	        SortWorkspace workspace = new SortWorkspace(values);
 28	
 29	        for (long exponent = 1; maxValue / exponent > 0; exponent *= RADIX) {
 30	            countingSortByDigit(
 31	                workspace.source(),
 32	                workspace.target(),
 33	                workspace.counts(),
 34	                exponent
 35	            );
 36	            workspace.swapBuffers();
 37	        }
 38	
 39	        workspace.copyResultBackIfNeeded();
 40	    }
 41	
 42	    private static InputAnalysis analyze(int[] values) {
 43	        Objects.requireNonNull(values, "values");
 44	        if (values.length == 0) {
 45	            return new InputAnalysis(values, 0);
 46	        }
 47	
 48	        int maxValue = values[0];
 49	
 50	        for (int index = 0; index < values.length; index++) {
 51	            int value = values[index];
 52	            if (value < 0) {
 53	                throw new IllegalArgumentException(
 54	                    "Radix sort only supports non-negative integers."
 55	                );
 56	            }
 57	
 58	            if (value > maxValue) {
 59	                maxValue = value;
 60	            }
 61	        }
 62	
 63	        return new InputAnalysis(values, maxValue);
 64	    }
 65	
 66	    private static void countingSortByDigit(
 67	        int[] source,
 68	        int[] target,
 69	        int[] counts,
 70	        long exponent
 71	    ) {
 72	        Arrays.fill(counts, 0);
 73	
 74	        for (int value : source) {
 75	            counts[digitAt(value, exponent)]++;
 76	        }
 77	
 78	        for (int digit = 1; digit < RADIX; digit++) {
 79	            counts[digit] += counts[digit - 1];
 80	        }
 81	
 82	        for (int index = source.length - 1; index >= 0; index--) {
 83	            int value = source[index];
 84	            int digit = digitAt(value, exponent);
 85	            target[--counts[digit]] = value;
 86	        }
 87	    }
 88	
 89	    private static int digitAt(int value, long exponent) {
 90	        return (int) ((value / exponent) % RADIX);
 91	    }
 92	
 93	    private static final class SortWorkspace {
 94	        private final int[] originalValues;
 95	        private final int[] buffer;
 96	        private final int[] counts = new int[RADIX];
 97	        private int[] source;
 98	        private int[] target;
 99	
100	        private SortWorkspace(int[] values) {
101	            this.originalValues = values;
102	            this.buffer = new int[values.length];
103	            this.source = values;
104	            this.target = buffer;
105	        }
106	
107	        private int[] source() {
108	            return source;
109	        }
110	
111	        private int[] target() {
112	            return target;
113	        }
114	
115	        private int[] counts() {
116	            return counts;
117	        }
118	
119	        private void swapBuffers() {
120	            int[] previousSource = source;
121	            source = target;
122	            target = previousSource;
123	        }
124	
125	        private void copyResultBackIfNeeded() {
126	            if (source != originalValues) {
127	                System.arraycopy(source, 0, originalValues, 0, originalValues.length);
128	            }
129	        }
130	    }
