133	        private final int[] values;
134	        private final int maxValue;
135	
136	        private InputAnalysis(int[] values, int maxValue) {
137	            this.values = values;
138	            this.maxValue = maxValue;
139	        }
140	
141	        private int[] values() {
142	            return values;
143	        }
144	
145	        private int maxValue() {
146	            return maxValue;
147	        }
148	    }
149	}

